-- Quantified LIKE and POSIX operators, their negations, OPERATOR() and
-- parenthesized subquery forms, type resolution, and view deparsing.
select 'abc' ~ any (array['^a', 'z']);
select 'abc' ~ all (array['^a', 'z']);
select 'abc' ~* any (array['^A']);
select 'abc' !~ any (array['^a', 'z']);
select 'abc' !~* all (array['^A']);
select 'abc' like any (array['a%', 'z']);
select 'abc' ilike all (array['A%', '%C']);
select 'abc' not like any (array['a%']);
select 'abc' similar to any (array['a%']);
select 'abc' ~~ any (array['a%']);
select 'abc' ~ any (select '^a');
select 'abc' ~ any ('{^a,b}');
select 1 < any (array[0, 2]);
select 'abc' ~ any (array[null, 'z']);
select 'abc' ~ any (null::text[]);
select x ~ any (array['^a']) from (values ('abc'), ('xyz')) v(x);
select 'abc' ^@ any (array['ab']);
select 'abc' ~ any (array['(']);
select 'abc' ~ some (array['c$']);
select '1.2.3.4'::inet << any (array['1.2.0.0/16'::cidr]);
select 'abc' operator(pg_catalog.~) any (array['^a']);
select 'abc' ~ any (values ('a'));
select 1 ~ any (array['a']);
select 'a' ~ any (array[1]);
select 'abc'::name ~ any (array['^a']);
select 'abc'::varchar ~ any (array['^a'::varchar]);
select 'abc'::char(3) ~* all (array['A', 'C']);
select 'abc' ~ all (array[]::text[]);
select 'abc' !~ all (array['x', 'y']);
select x from (values ('abc'),('xbc')) v(x) where x ~ any (array['^a', '^q']);
create table qr (t text, p text[]);
insert into qr values ('abc', '{^a,z}'), ('xyz', '{^a}'), (null, '{a}'), ('a', null);
select t, t ~ any (p), t ~ all (p), t !~* any (p) from qr order by 1;
select any (array[1]);
select 'abc' ~ any (array['a'], array['b']);
select pg_get_viewdef('v_regex_any');
create view v_regex_any as select t ~ any (p) as a, t !~* all (p) as b from qr;
select pg_get_viewdef('v_regex_any');
drop view v_regex_any;
drop table qr;
create table qr (t text, p text[]);
create view v1 as select t like any (p) as a, t = any (p) as b from qr;
select pg_get_viewdef('v1');
create view v2 as select t ~ 'a' as a, t !~* 'b' as b from qr;
select pg_get_viewdef('v2');
select 1 = any (values (1));
select 1 = any ((select 1));
select 'a' like any (array[1]);
create view v3 as select t ~ any (p) as a, t !~* all (p) as b, t not like any (p) as c, t = any (array['a', 'b']) as d, t < all (array[t]) as e, t ilike any (array['%a']) as f from qr;
select pg_get_viewdef('v3');
select t ~ any (p), t !~* all (p), t not like any (p), t not ilike all(p) from (values ('abc', '{^a,B}'::text[]), ('x', '{}'), (null, '{a}'), ('a', '{a,null}')) v(t, p);
